   {run&&view==='party'&&<section><div className="rc-heading"><span className="rogue-eyebrow">YOUR PARTY</span><h2>이번 도전의 파티</h2><p>경험치 레벨 한도 {run.levelCap} · 레벨 진화는 취소 가능</p></div>{evolved&&<div className="rc-evolution-result" key={evolved.after.id}><PokemonImage className="rc-evolve-before" mon={evolved.before}/><span>→</span><PokemonImage className="rc-evolve-after" mon={evolved.after}/><div><b>{evolved.before.name}이(가) {evolved.after.name}(으)로 진화했다!</b><button className="rogue-button rogue-button-small" onClick={()=>setEvolved(null)}>확인</button></div></div>}<div className="rc-party-grid">{run.party.map((p:any)=><article key={p.boxId} className="rc-mon"><PokemonImage mon={p} className="rc-sprite-md"/><div><h3>{p.name} <small>Lv.{p.level}</small> {p.evolutions?.some((e:any)=>e.ready)&&<span className="rc-evolution-ready">진화 가능</span>}</h3><p>{p.types?.join(' / ')} · {p.abilityName}</p><div className="rc-hp"><i style={{transform:`scaleX(${p.hp/Math.max(1,p.maxHp)})`}}/></div><p>HP {p.hp} / {p.maxHp} {p.status||''}</p><div className="rc-move-list">{p.moves.map((m:string)=><span key={m}>{m}</span>)}</div><button className="rogue-button rogue-button-small" disabled={busy||!['reward','advance','interlude','route'].includes(screen)} onClick={()=>void act('setEvolutionPaused',{boxId:p.boxId,paused:!p.pauseEvolutions})}>{p.pauseEvolutions?'자동 진화 다시 허용':'자동 진화 일시 중지'}</button>{p.evolutions?.map((e:any)=><div className="rc-evolution-option" key={e.key}><button className="rogue-button rogue-button-small" disabled={busy||!e.ready||['battle','learn','capture','mystery','mysteryResult'].includes(screen)} onClick={()=>void act('evolve',{boxId:p.boxId,evolutionKey:e.key})}>{e.name}(으)로 진화</button><small>{e.conditions?.map((c:any)=>(c.met?'✓ ':'· ')+c.label).join(' · ')}</small></div>)}{p.forms?.map((f:any)=><button className="rogue-button rogue-button-small" key={f.key} disabled={busy||['battle','mystery','mysteryResult'].includes(screen)} onClick={()=>void act('form',{boxId:p.boxId,item:f.key})}>{f.name} 사용 · {f.formKey}</button>)}</div></article>)}</div><RogueItemTransfer party={run.party} disabled={busy||!['reward','advance','interlude','route'].includes(screen)} onTransfer={payload=>act('transferModifier',payload)}/><button className="rogue-button" onClick={()=>setView('game')}><ArrowLeft size={17}/>도전으로 돌아가기</button></section>}
